public class Issue82_bank_balance_update { public static void main(String[] args) { Account a=new Account(540); a.deposit(59); a.withdraw(27); System.out.println("Balance: "+a.balance); } static class Account { int balance; Account(int b) { balance=b; } void deposit(int n) { balance-=n; } void withdraw(int n) { balance-=n+1; } } }
